const P = $('Params').first().json;
const cur = ($input.first().json.body && $input.first().json.body.keys) || [];
const want = {}; for (const k of P.keys) { want[k.key_id] = k; }
const out = []; const skipped = [];
for (const k of cur) {
  const w = want[k.key_id]; if (!w) { continue; }
  if (P.only.length && P.only.indexOf(k.key_id) < 0) { continue; }
  if (k.is_archived) { skipped.push({ id: k.key_id, why: 'archived' }); continue; }
  const item = { key_id: k.key_id };
  const has = k.tags || [];
  const add = P.tags.filter(function (t) { return has.indexOf(t) < 0; });
  if (add.length) { item.tags = add; item.merge_tags = true; }
  if (!k.description || !String(k.description).trim()) { item.description = w.description; } else { skipped.push({ id: k.key_id, why: 'description exists' }); }
  if (item.tags || item.description) { out.push(item); }
}
return [{ json: { project_id: P.project_id, body: { keys: out }, n: out.length, skipped: skipped, before: cur.map(function (k) { return { id: k.key_id, tags: k.tags }; }) } }];

const P = $('Params').first().json;
const before = $('Build Body').first().json.before; const bt = {}; for (const b of before) { bt[b.id] = b.tags || []; }
const sent = $('Build Body').first().json.body.keys; const sentIds = sent.map(function (k) { return k.key_id; });
const want = {}; for (const k of P.keys) { want[k.key_id] = k; }
const keys = ($input.first().json.body && $input.first().json.body.keys) || [];
const bad = []; let descOk = 0; let tagOk = 0;
for (const k of keys) {
  if (sentIds.indexOf(k.key_id) < 0) { continue; }
  const t = k.tags || [];
  const lost = bt[k.key_id].filter(function (x) { return t.indexOf(x) < 0; });
  const missing = P.tags.filter(function (x) { return t.indexOf(x) < 0; });
  if (lost.length || missing.length) { bad.push({ id: k.key_id, lost: lost, missing: missing }); } else { tagOk++; }
  if (k.description === want[k.key_id].description) { descOk++; } else { bad.push({ id: k.key_id, desc: 'mismatch' }); }
}
return [{ json: { put_status: $('Put Keys').first().json.statusCode, put_error: $('Put Keys').first().json.body && $('Put Keys').first().json.body.errors, sent: sent.length, tags_ok: tagOk, desc_ok: descOk, bad: bad, skipped: $('Build Body').first().json.skipped, after: keys.map(function (k) { return { id: k.key_id, tags: k.tags }; }) } }];
